#define _GNU_SOURCE
#include <stdlib.h>
#include <sys/types.h>
#include <sys/uio.h>
int main(void) {
    char buf1[10];
    char buf2[10];
    pid_t pid = 10; /* PID of remote process */
    struct iovec local[2];
    struct iovec remote[1];
    local[0].iov_base = buf1;
    local[0].iov_len = 10;
    local[1].iov_base = buf2;
    local[1].iov_len = 10;
    remote[0].iov_base = (void *) 0x10000;
    remote[0].iov_len = 20;
    ssize_t nread = process_vm_writev(pid, local, 2, remote, 1, 0);
    if (nread != 20) exit(EXIT_FAILURE);
    exit(EXIT_SUCCESS);
}
